create table if not exists creator_interop_public_projections (id uuid primary key default gen_random_uuid(), source_type text not null, source_id uuid not null, purpose text not null, payload jsonb not null, source_version text not null, issuer text not null, jurisdiction text not null, fresh_at timestamptz not null, disputed boolean not null default false, suspended boolean not null default false, revoked boolean not null default false, published_at timestamptz, withdrawn_at timestamptz);
create table if not exists creator_interop_notifications (id uuid primary key default gen_random_uuid(), notification_type text not null, instrument_id uuid, signed_payload jsonb not null, content_hash text not null, status text not null, sent_at timestamptz, created_at timestamptz not null default now());
create table if not exists creator_interop_audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid, action text not null, resource_type text not null, resource_id uuid, policy_version text not null, schema_version text not null, jurisdiction text not null, source_manifest_id uuid, event_payload jsonb not null, created_at timestamptz not null default now());
create table if not exists creator_interop_outbox (id uuid primary key default gen_random_uuid(), event_type text not null, aggregate_type text not null, aggregate_id uuid not null, payload jsonb not null, idempotency_key text not null unique, available_at timestamptz not null default now(), processed_at timestamptz, attempts int not null default 0);
